WITH supplied(name) AS (VALUES ('Aaron Berg'),('Abby Washuta'),('Adam Gabel'),('Adam Muller'),('Adam Nate Levine'),('Alexis Bradby'),('Amada Caba'),('André de Freitas'),('Andy Aluise'),('Anna Bianco'),('April Boddie'),('Ben Callahan'),('Ben Frank'),('Brandon Trusso'),('Byron Austin'),('Cab Washington'),('Caitlin Peluffo'),('Caitlin Reese'),('Cameron Stafford'),('Candyce Cook'),('Carmen Lagala'),('Carmen Lynch'),('Chris Condren'),('Chris Hamilton'),('Chris Keise'),('Chris Reiter'),('Christian Finnegan'),('Christy Miller'),('Connor Meade'),('Cooper Kim'),('Corinne Fisher'),('Cory Kahaney'),('Dave Caggiano'),('Derek Gaines'),('Derick Gonzalez'),('Dj Collins'),('Dominic Leonelli'),('Doug Uram'),('Drew Beekler'),('Erica Spera'),('Erin Jackson'),('Esther Chen'),('Gabe Dorado'),('Gibran Saleem'),('Graham Kay'),('Igor Martinez'),('J Smitty'),('Ja-Ron Young'),('Jake Silberman'),('Jake Velazquez'),('James Mwaura'),('Jatty Robinson'),('Jenae Boston'),('Jenny Saldana'),('Joe Russell'),('Joseph Rosenzweig'),('Jourdain Fisher'),('Julia Kastner'),('Julianna Dudley'),('Kevin Dombrowski'),('Leclerc Andre'),('Linette Palladino'),('Liza Treyger'),('Malorie Bryant'),('Mark Normand'),('Matt Bowman'),('Monte Marshall'),('Neko White'),('Nikhil Mehta'),('Nikki MacCallum'),('Noah Miller'),('Patrick Holbert'),('Peter Revello'),('Philipp Kostelecky'),('Rachel Lenihan'),('Reuben Wolf'),('Rich Francese'),('Richie Redding'),('Royale Watkins'),('Ryan O''Toole'),('Ryan Thomas'),('Seaton Smith'),('Shane Torres'),('Shaun Eli'),('Shyam Subramanian'),('Soo Ra'),('Talib Babb'),('Tanner Riley'),('Teressa DeGaetano'),('Tina Zhu'),('Tomas Liebel'),('Troy Alan'),('Tyler Groce'),('Vlad Caamano'),('Zach Braviette')) SELECT supplied.name AS source_name,c.id,c.uuid,c.name,c.visible,c.parent_comedian_id,EXISTS(SELECT 1 FROM comedian_deny_list d WHERE LOWER(d.name)=LOWER(supplied.name)) AS denied,EXISTS(SELECT 1 FROM tagged_comedians tc JOIN tags t ON t.id=tc.tag_id WHERE tc.comedian_id=c.uuid AND NOT t.user_facing) AS nonpublic_tag FROM supplied LEFT JOIN comedians c ON LOWER(c.name)=LOWER(supplied.name) ORDER BY supplied.name,c.id;
